      }"
   }
}

PROTO AvatarURL [
   eventIn SFTime select
   eventOut SFString selected
   eventOut SFBool exit
   exposedField SFString URL ""
]
{
   Script {
      eventIn SFTime select IS select
      eventOut SFString selected IS selected
      eventOut SFBool exit IS exit
      eventIn SFString URL IS URL
      url "vrmlscript: 
      function URL(v,t) {
      URL = v;
      }
      function select(value, time)
      { 
      selected = URL; 
      exit = TRUE;
      }"
   }
