 DEF spinner TimeSensor {
  cycleInterval 0.1
  loop TRUE
  enabled FALSE
}


DEF spin Script {
  eventIn SFTime startRevolving
  eventIn SFTime enable
  eventIn SFTime disable
  eventIn SFTime right
  eventIn SFTime left
  eventIn SFTime back
  eventIn SFTime front
  eventIn SFTime face
  eventIn SFTime full
  eventOut SFBool fullon
  eventOut SFBool faceon
  eventOut SFBool able
  eventOut SFRotation revolve
  field SFFloat angle 0.5



  url "javascript:
    function startRevolving() {
      revolve[0] = 0;
      revolve[1] = 1;
      revolve[2] = 0;
      revolve[3] = angle;
      angle += 0.1;
    }


	function enable(t) {
	 if (t) able = true;
	   	}

	function disable(t) {
	if (t) able = false;
	}

	function face(t){
	 if (t) faceon = true;
	}

	function full(t){
		if (t) fullon = true;
	}

	function front(t) {
	  revolve[0] = 0;
      revolve[1] = 1;
      revolve[2] = 0;
      revolve[3] = 0;
	}

	function right(t) {
	  revolve[0] = 0;
      revolve[1] = 1;
      revolve[2] = 0;
      revolve[3] = 1.57;
	}

	function left(t) {
	  revolve[0] = 0;
      revolve[1] = 1;
      revolve[2] = 0;
      revolve[3] = -1.57;
	}

	function back(t) {
	  revolve[0] = 0;
      revolve[1] = 1;
      revolve[2] = 0;
      revolve[3] = 3.15;
	}

  "
}


 ROUTE Touch16.isActive TO	spinner.enabled
