  ROUTE Touch11.touchTime TO spin.front
  ROUTE	Touch15.touchTime TO spin.face
  ROUTE	spin.faceon	TO face.set_bind
  ROUTE	Touch18.touchTime TO spin.full
  ROUTE	spin.fullon TO full.set_bind

DEF CameraScript Script {
   eventIn SFVec3f	set_translation
   eventIn SFRotation	set_rotation
   eventOut MFString	translation_changed
   eventOut MFString	rotation_changed
   field	SFString	Temp ""

   url "javascript:
   function trunc(value) {
	return Math.round(value*100)/100;
   }
   function set_translation(value)
   {
	Temp = 'Position:      ' + trunc(value.x) + '  ' + trunc(value.y) + '  ' + trunc(value.z);
	translation_changed[0] = Temp;
   }
   function set_rotation(value)
   {
	Temp = 'Orientation: ' + trunc(value.x) + '  ' + trunc(value.y) + '  ';
	Temp = Temp + trunc(value.z) + '  ' + trunc(value.angle);
	rotation_changed[0] = Temp;
   }
   "
}
  
ROUTE HudProximity.orientation_changed  TO CameraScript.set_rotation
ROUTE HudProximity.position_changed  TO CameraScript.set_translation


# ROUTE AV.children_changed TO Avatarscript.set_avatar
ROUTE Avatar.children_changed TO Avatarscript.set_avatar

ROUTE HudProximity.position_changed TO HudProximity.set_center
ROUTE HudProximity.orientation_changed  TO HudGeometry.set_rotation
ROUTE HudProximity.position_changed  TO HudGeometry.set_translation
